#include <bits/stdc++.h>
using namespace std;

long long factorial(int n) {
    long long res = 1;
    for (int i = 2; i <= n; ++i) {
        res *= i;
    }
    return res;
}

long long A(int n, int k) {
    return factorial(n) / factorial(n - k);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;
    if (n == 1) {
        cout << 0 << "\n";
        return 0;
    }
    vector<long long> current_zs(1, 1);
    long long total_result = 0;
    for (int i = 2; i <= n; ++i) {
        int size_new_zs = (i * i) / 2;
        vector<long long> new_zs(size_new_zs, 0);
        for (size_t j = 0; j < current_zs.size(); ++j) {
            for (int k = 0; k < i; ++k) {
                if (current_zs[j] > 0) {
                    int index = i - k - 1 + j;
                    if (index >= 0 && index < size_new_zs) {
                        new_zs[index] += current_zs[j];
                    }
                }
            }
        }
        int len_curr = (int)current_zs.size();
        vector<long long> prefix_sums(len_curr + 1, 0);
        for (int w = len_curr - 1; w >= 0; --w) {
            prefix_sums[w] = (prefix_sums[w + 1] + current_zs[w]) % mod;
        }
        vector<long long> e_vals(len_curr + 1, 0);
        vector<long long> f_vals(len_curr + 1, 0);
        for (int w = 0; w < len_curr; ++w) {
            e_vals[w + 1] = (e_vals[w] + prefix_sums[w]) % mod;
            f_vals[w + 1] = (f_vals[w] - (long long)w * prefix_sums[w]) % mod;
            if (f_vals[w + 1] < 0) f_vals[w + 1] += mod;
        }
        long long total_ccc = 0;
        for (int jj = 0; jj < len_curr; ++jj) {
            int L = jj + 2;
            int R = std::min(len_curr - 1, i + jj);
            long long ccc = 0;
            if (R >= L) {
                long long e_diff = e_vals[R + 1] - e_vals[L];
                long long f_diff = f_vals[R + 1] - f_vals[L];
                e_diff %= mod;
                f_diff %= mod;
                ccc = ((e_diff * (i + 1 + jj)) % mod + f_diff) % mod;
            }
            total_ccc = (total_ccc + ccc * current_zs[jj]) % mod;
        }
        long long comb = A(n, n - i);
        total_result = (total_result + total_ccc) % mod;
        total_result = (total_result + (total_result * comb) % mod) % mod;
        current_zs = new_zs;
    }
    cout << total_result % mod << "\n";
    return 0;
}
